    'By checking this option you will be able to provide service at customer location' => 'من خلال تحديد هذا الخيار، ستتمكن تقديم الخدمة في موقع العميل',
    'By checking this option you will be able to provide service at your business location' => 'من خلال تحديد هذا الخيار، ستتمكن تقديم الخدمة في موقع عملك',
    'By disabling Partial Payment, customers must pay the full bill using a single payment method.' => 'من خلال تعطيل الدفع الجزئي، يجب على العملاء دفع الفاتورة كاملة باستخدام طريقة دفع واحدة.',
    'By enabling Partial Payment, customers will be able to pay a portion of their bill using wallet balance and complete the remaining payment through the selected payment options.' => 'ومن خلال تمكين الدفع الجزئي، سيتمكن العملاء دفع جزء فاتورتهم باستخدام رصيد المحفظة وإكمال الدفعة المتبقية خلال خيارات الدفع المحددة.',
    'By enabling manual login, customers will get the option to create an account and log in using the necessary credentials & password in the app & website' => 'من خلال تمكين تسجيل الدخول اليدوي، سيحصل العملاء على خيار إنشاء حساب وتسجيل الدخول باستخدام بيانات الاعتماد وكلمة المرور اللازمة في التطبيق والموقع الإلكتروني.',
    'By providing valid SMTP credentials, the platform can deliver system notifications, OTPs, password reset emails, booking updates, and other automated messages.' => 'من خلال توفير بيانات اعتماد SMTP صالحة، يمكن للنظام تقديم إشعارات النظام، ورسائل OTP، ورسائل البريد الإلكتروني لإعادة تعيين كلمة المرور، وتحديثات الحجز، والرسائل الآلية الأخرى.',
    'By selecting Cash After Service Will make it available as a payment option for customers during the checkout process' => 'من خلال تحديد خدمة Cash After Service، سيتم إتاحتها كخيار دفع للعملاء أثناء عملية الدفع',
    'By selecting commission based business model provider can run business with you based on commission based payment per booking.' => 'من خلال اختيار مشرف نموذج الأعمال القائم على العمولة، يمكنه إدارة الأعمال معك على أساس الدفع على أساس العمولة لكل حجز.',
    'By selecting digital payment will make it available as a payment option for customers during the checkout process.' => 'من خلال تحديد الدفع الرقمي، سيتم إتاحته كخيار دفع للعملاء أثناء عملية الدفع.',
    'By selecting instant booking, customers instantly book a service for a specific date without delays.' => 'من خلال تحديد الحجز الفوري، يقوم العملاء بحجز الخدمة على الفور لتاريخ محدد دون تأخير.',
    'By selecting offline payment will make it available as a payment option for customers during the checkout process.' => 'سيؤدي تحديد الدفع دون الاتصال بالإنترنت إلى إتاحته كخيار دفع للعملاء أثناء عملية الدفع.',
    'By selecting schedule booking, to book a service customers have to select specific date and time to book a service.' => 'من خلال تحديد جدول الحجز، لحجز خدمة، يتعين على العملاء تحديد تاريخ ووقت محددين لحجز الخدمة.',
    'By selecting the subscription-based business model, provider can operate with you using a chosen subscription package.' => 'من خلال تحديد نموذج الأعمال القائم على الاشتراك، يمكن لمشرف الخدمة العمل معك باستخدام حزمة الاشتراك المختارة.',
    'By switching this feature ON, Customer can pay with wallet balance & partially pay from other payment gateways.' => 'من خلال تشغيل هذه الميزة، يمكن للعميل الدفع باستخدام رصيد المحفظة والدفع جزئيًا بوابات الدفع الأخرى.',
    'By turning off availability mode, you will not get any new booking request from customers and customer will that you are currently unavailable to provide service' => 'من خلال إيقاف تشغيل وضع الإتاحة، لن تحصل على أي طلب حجز جديد العملاء وسيعلم العميل أنك غير متاح حاليًا لتقديم الخدمة',
