    'How to Set Up & Use - Add the Offline Payment Method to the list by entering the method name & required information, and enable it, and saving it to make it available for use.' => 'كيفية الإعداد والاستخدام - أضف طريقة الدفع دون اتصال بالإنترنت إلى القائمة عن طريق إدخال اسم الطريقة والمعلومات المطلوبة وتمكينها وحفظها لإتاحتها للاستخدام.',
    'How to Set Up & Use - choose the digital payment method you want to use, enter the required provider details (like API or merchant info), turn it on, and save to activate it for customers.' => 'كيفية الإعداد والاستخدام - اختر طريقة الدفع الرقمية التي تريد استخدامها، وأدخل تفاصيل المشرف المطلوبة (مثل واجهة برمجة التطبيقات أو معلومات التاجر)، وقم بتشغيلها، واحفظها لتنشيطها للعملاء.',
