    'Identity_Type' => 'نوع الهوية',
    'If Email verification is on, Customers must verify their Email with an verification code to complete the signup process.' => 'إذا كان التحقق البريد الإلكتروني قيد التشغيل، فيجب على العملاء التحقق بريدهم الإلكتروني باستخدام رمز التحقق لإكمال عملية التسجيل.',
    'If Phone Number verification is on, Customers must verify their Phone Number with an OTP to complete the signup process.' => 'إذا كان التحقق رقم الهاتف قيد التشغيل، فيجب على العملاء التحقق رقم هاتفهم باستخدام كلمة مرور لمرة واحدة (OTP) لإكمال عملية التسجيل.',
    'If SMTP configuration is disabled or incorrect, the system will not be able to send any email notifications.' => 'إذا تم تعطيل تكوين SMTP أو كان غير صحيح، فلن يتمكن النظام إرسال أي إشعارات عبر البريد الإلكتروني.',
    'If disabled Subscription, All subscriber moved to commission and providers have to give a certain percentage of commission to admin for every booking request' => 'إذا تم تعطيل الاشتراك، فسيتم نقل جميع المشتركين إلى العمولة ويجب على المشرفين إعطاء نسبة معينة العمولة للمسؤول لكل طلب حجز',
    'If disabled customers and provider will not receive notifications on their devices' => 'إذا تم تعطيل العملاء والمشرف، فلن يتلقوا إشعارات على أجهزتهم',
    'If disabled customers can not pay through this payment methods' => 'إذا لم يتمكن العملاء المعاقين الدفع خلال طرق الدفع هذه',
    'If enable this, newly uploaded/created files and data will store to 3rd party storage.' => 'إذا قمت بتمكين هذا، فسيتم تخزين الملفات والبيانات التي تم تحميلها/إنشاءها حديثًا على مساحة تخزين تابعة لجهة خارجية.',
    'If enable this, newly uploaded/created files and data will store to local storage.' => 'إذا قمت بتمكين هذا، فسيتم تخزين الملفات والبيانات التي تم تحميلها/إنشاءها حديثًا على وحدة التخزين المحلية.',
    'If enabled System will store all files and images to 3rd party storage' => 'في حالة تمكين النظام، سيقوم النظام بتخزين جميع الملفات والصور على مساحة تخزين تابعة لجهة خارجية',
    'If enabled System will store all files and images to local storage' => 'في حالة تمكين النظام، سيقوم النظام بتخزين جميع الملفات والصور على وحدة التخزين المحلية',
    'If enabled customers can only pay through this payment methods' => 'إذا تم تمكين العملاء، فيمكنهم الدفع فقط خلال طرق الدفع هذه',
    'If enabled, Serviceman can cancel a booking request after it has been place' => 'إذا تم تمكينه، فيمكن للفني إلغاء طلب الحجز بعد إجرائه',
    'If enabled, Serviceman can edit a booking request after it has been place' => 'إذا تم تمكينه، فيمكن للفني تعديل طلب الحجز بعد تقديمه',
    'If enabled, provider can delete account' => 'إذا تم تمكينه، يمكن للمشرف حذف الحساب',
    'If enabled, providers can cancel a booking even after it has been placed.' => 'إذا تم تمكينه، فيمكن للمشرفين إلغاء الحجز حتى بعد إجرائه.',
    'If enabled, providers can do self-registration from the admin landing page, provider panel & app, and customer website & app.' => 'في حالة التمكين، يمكن للمشرفين إجراء التسجيل الذاتي الصفحة المقصودة للمسؤول، ولوحة المشرف والتطبيق، وموقع العميل والتطبيق.',
    'If enabled, providers can edit a booking request after it has been placed' => 'إذا تم تمكينه، فيمكن لالمشرفين تعديل طلب الحجز بعد تقديمه',
    'If enabled, providers can review reply' => 'إذا تم تمكينه، فيمكن لالمشرفين مراجعة الرد',
    'If enabled, the provider will be automatically suspended by the system when their ‘Cash in Hand’ limit is exceeded.' => 'في حالة التمكين، سيتم تعليق المشرف تلقائيًا قبل النظام عند تجاوز حد "النقد في الصندوق" الخاص به.',
    'If no access is selected, employees with this role can only view the section for which permissions are granted; they cannot perform any actions.' => 'إذا لم يتم تحديد أي وصول، فيمكن للموظفين الذين لديهم هذا الدور فقط عرض القسم الذي تم منح الأذونات له؛ لا يمكنهم تنفيذ أي إجراءات.',
    'If the maximum limit is exceeded, the provider will be suspended and will not receive any service requests.' => 'في حالة تجاوز الحد الأقصى، سيتم إيقاف المشرف ولن يتلقى أي طلبات خدمة.',
    'If the required permissions are not in place, you’ll need to manually configure the cron job by adding the following command to your server’s crontab' => 'إذا لم تكن الأذونات المطلوبة موجودة، فستحتاج إلى تكوين مهمة cron يدويًا عن طريق إضافة الأمر التالي إلى crontab الخاص بخادمك',
    'If there is any update available in the admin panel and the previous app will not work with it.' => 'إذا كان هناك أي تحديث متاح في لوحة الإدارة ولن يعمل التطبيق السابق معه.',
    'If this feature is active customers get the otp through firebase.' => 'إذا كانت هذه الميزة نشطة، فسيحصل العملاء على كلمة مرور لمرة واحدة خلال Firebase.',
    'If want to Update it for all upcoming bookings' => 'إذا كنت ترغب في تحديثه لجميع الحجوزات القادمة',
    'If you activate reCAPTCHA, please ensure that reCAPTCHA v3 is properly set up beforehand.' => 'إذا قمت بتنشيط reCAPTCHA، فيرجى التأكد إعداد reCAPTCHA v3 بشكل صحيح مسبقًا.',
    'If you approve it, it will remain expired.' => 'إذا وافقت عليه، فإنه سيظل منتهية الصلاحية.',
    'If you are using a different path, find your mysqldump by running the command "which mysqldump" or "locate mysqldump" in your terminal, or ask your server provider.' => 'إذا كنت تستخدم مسارًا مختلفًا، فابحث عن mysqldump الخاص بك عن طريق تشغيل الأمر "what mysqldump" أو "locate mysqldump" في المحطة الطرفية لديك، أو اطلب مشرف الخادم الخاص بك.',
    'If you cancel the subscription, after :countDays days the Provider will no longer be able to run the business before subscribe a new plan' => 'إذا قمت بإلغاء الاشتراك، بعد أيام :countDays، لن يتمكن المشرف تشغيل الأعمال قبل الاشتراك في خطة جديدة',
    'If you close now, the progress made so far will be saved.' => 'إذا قمت بالإغلاق الآن، فسيتم حفظ التقدم الذي تم إحرازه حتى الآن.',
    'If you close the tab, the progress made will be saved but remaining content will not be translated.' => 'إذا قمت بإغلاق علامة التبويب، فسيتم حفظ التقدم المحرز ولكن لن تتم ترجمة المحتوى المتبقي.',
    'If you do not have any project yet, create one with the website name.' => 'إذا لم يكن لديك أي مشروع حتى الآن، قم بإنشاء واحد باسم الموقع.',
    'If you do not need a force update, just insert zero (0) here and ignore it.' => 'إذا لم تكن بحاجة إلى تحديث فرض، فما عليك سوى إدخال الصفر (0) هنا وتجاهله.',
    'If you don’t have any project before. Create one with the website name' => 'إذا لم يكن لديك أي مشروع قبل. قم بإنشاء واحدة باسم موقع الويب',
    'If you have not created any project for your application yet, please create one first.' => 'إذا لم تكن قد أنشأت أي مشروع لتطبيقك بعد، فيرجى إنشاء واحد أولاً.',
    'If you have questions or need assistance, contact our support team.' => 'إذا كانت لديك أسئلة أو كنت بحاجة إلى المساعدة، فاتصل بفريق الدعم لدينا.',
    'If you need assistance, contact our support team.' => 'إذا كنت بحاجة إلى المساعدة، اتصل بفريق الدعم لدينا.',
    'If you select repeat booking, the customer can place the same service booking for multiple dates under one booking' => 'إذا قمت بتحديد الحجز المتكرر، فيمكن للعميل إجراء نفس حجز الخدمة لتواريخ متعددة ضمن حجز واحد',
    'If you switch this newly uploaded created files & data will store to 3rd party storage' => 'إذا قمت بتبديل هذه الملفات والبيانات التي تم إنشاؤها حديثًا والتي تم تحميلها، فسيتم تخزينها في مساحة تخزين تابعة لجهة خارجية',
    'If you switch this newly uploaded created files & data will store to local storage' => 'إذا قمت بتبديل هذه الملفات والبيانات التي تم إنشاؤها حديثًا والتي تم تحميلها، فسيتم تخزينها على وحدة التخزين المحلية',
    'If you turn of the availability status, this page will not show in the customer app and website' => 'إذا قمت بإيقاف حالة التوفر، فلن تظهر هذه الصفحة في تطبيق العميل وموقع الويب',
    'If you turn off customer can`t pay through this payment gateway.' => 'إذا قمت بإيقاف تشغيل العميل، فلن يتمكن الدفع خلال بوابة الدفع هذه.',
    'If you turn off customer can`t pay through this payment geteway.' => 'إذا قمت بإيقاف تشغيل العميل، فلن يتمكن الدفع خلال بوابة الدفع هذه.',
    'If you turn on The Status, this payment will show in dropdown list when withdraw request sent to admin.' => 'إذا قمت بتشغيل الحالة، فسوف تظهر هذه الدفعة في القائمة المنسدلة عند إرسال طلب السحب إلى المشرف.',
    'If you turn on the switch, this feature will be active and customers can make scheduled orders after the restriction time ends.' => 'إذا قمت بتشغيل المفتاح، فستكون هذه الميزة نشطة ويمكن للعملاء تقديم طلبات مجدولة بعد انتهاء وقت التقييد.',
    'If you want to use third-party storage, set up the connection with :third_party_storage_link.' => 'إذا كنت تريد استخدام وحدة تخزين تابعة لجهة خارجية، فقم بإعداد الاتصال باستخدام رابط تخزين الجهة الخارجية :third.',
    'If you want, you can activate all 3 options based on your business need.' => 'إذا أردت، يمكنك تفعيل جميع الخيارات الثلاثة بناءً على احتياجات عملك.',
    'If your servers DUMP BINARY PATH does not match the following input field path, you must update it.' => 'إذا كانت خوادمك DUMP BINARY PATH لا تتطابق مع مسار حقل الإدخال التالي، فيجب عليك تحديثه.',
