    'It looks like your Apple ID Login configuration is not set up yet.' => 'يبدو أن تكوين تسجيل الدخول إلى معرف Apple الخاص بك لم يتم إعداده بعد.',
    'It looks like your Apple ID Login configuration is not set up yet. To enable the Apple ID Login option, please set up the Apple ID configuration first.' => 'يبدو أن تكوين تسجيل الدخول إلى معرف Apple الخاص بك لم يتم إعداده بعد. لتمكين خيار تسجيل الدخول إلى معرف Apple، يرجى إعداد تكوين معرف Apple أولاً.',
    'It looks like your Apple configuration is not set up yet.' => 'يبدو أن تكوين Apple الخاص بك لم يتم إعداده بعد.',
    'It looks like your Email configuration is not set up yet.' => 'يبدو أن تكوين البريد الإلكتروني الخاص بك لم يتم إعداده بعد.',
    'It looks like your Facebook Login configuration is not set up yet.' => 'يبدو أن تكوين تسجيل الدخول إلى Facebook الخاص بك لم يتم إعداده بعد.',
    'It looks like your Facebook Login configuration is not set up yet. To enable the Facebook Login option, please set up the Facebook configuration first.' => 'يبدو أن تكوين تسجيل الدخول إلى Facebook الخاص بك لم يتم إعداده بعد. لتمكين خيار تسجيل الدخول عبر Facebook، يرجى إعداد تكوين Facebook أولاً.',
    'It looks like your Google configuration is not set up yet.' => 'يبدو أن تكوين Google الخاص بك لم يتم إعداده بعد.',
    'It looks like your Google configuration is not set up yet. To enable the OTP system, please set up the Google configuration first.' => 'يبدو أن تكوين Google الخاص بك لم يتم إعداده بعد. لتمكين نظام OTP، يرجى إعداد تكوين Google أولاً.',
    'It looks like your SMS configuration is not set up yet.' => 'يبدو أن تكوين الرسائل القصيرة الخاصة بك لم يتم إعداده بعد.',
    'It looks like your server might not have the necessary permissions to automatically set up the cron job.' => 'يبدو أن خادمك قد لا يمتلك الأذونات اللازمة لإعداد مهمة cron تلقائيًا.',
    'It looks like your social media configuration is not set up yet.' => 'يبدو أن تكوين الوسائط الاجتماعية الخاص بك لم يتم إعداده بعد.',
