    'Once you turn off the Category Status, the Provider can’t subscribe to the services of that category and the Customer can’t find the category & its service when they want to book' => 'بمجرد إيقاف تشغيل حالة الفئة، لا يمكن للمشرف الاشتراك في خدمات تلك الفئة ولا يمكن للعميل العثور على الفئة وخدمتها عندما يريد الحجز',
