    'That means if a user has an app below this version, the user must update the app first.' => 'وهذا يعني أنه إذا كان لدى المستخدم تطبيق أقل هذا الإصدار، فيجب على المستخدم تحديث التطبيق أولاً.',
    'The' => 'ال',
    'The :firebase_configuration_link page must be configured for notifications to work.' => 'يجب تكوين صفحة رابط التكوين :firebase حتى تعمل الإشعارات.',
    'The Access Key ID is a publicly accessible identifier used to authenticate requests to S3.' => 'معرف مفتاح الوصول هو معرف يمكن الوصول إليه بشكل عام ويستخدم لمصادقة الطلبات المقدمة إلى S3.',
    'The Admin Notification Setup for booking allows the administrator to configure how system notifications are sent and managed. Admin notifications can be delivered either manually or through Firebase, depending on the selected configuration' => 'يتيح إعداد إشعارات المسؤول للحجز للمسؤول تكوين كيفية إرسال إشعارات النظام وإدارتها. يمكن تسليم إشعارات المشرف إما يدويًا أو خلال Firebase، اعتمادًا على التكوين المحدد',
    'The Business name often serves as the primary identifier for your business as a legal entity.' => 'غالبًا ما يكون اسم النشاط التجاري بمثابة المعرّف الأساسي لنشاطك التجاري ككيان قانوني.',
    'The Country Name field, when setting up a business is essential for a multitude of reasons, spanning legal, operational, financial, and marketing aspects.' => 'يعد حقل اسم الدولة، عند إنشاء مشروع تجاري، ضروريًا لعدة أسباب، تشمل الجوانب القانونية والتشغيلية والمالية والتسويقية.',
    'The Cron Job PHP configuration error occurs when' => 'يحدث خطأ تكوين Cron Job PHP عندما',
    'The Customer will come to the your Location to receive the service' => 'سيأتي العميل إلى موقعك لتلقي الخدمة',
    'The PHP file path for a Cron Job refers to the location on the server where the PHP command to be executed is stored.' => 'يشير مسار ملف PHP لمهمة Cron إلى الموقع على الخادم حيث يتم تخزين البرنامج النصي PHP الذي سيتم تنفيذه.',
    'The Service Location will be available after this booking accepts or assign to a provider' => 'سيكون موقع الخدمة متاحًا بعد قبول هذا الحجز أو تعيينه لالمشرف',
    'The Service Location will be available after this booking assign to a provider' => 'سيكون موقع الخدمة متاحًا بعد تعيين هذا الحجز لالمشرف',
    'The ZipArchive class is not available' => 'فئة ZipArchive غير متوفرة',
    'The Zone Selection field helps you select the specific locations from where you provide services.' => 'يساعدك حقل اختيار المنطقة على تحديد المواقع المحددة التي تقدم الخدمات منها.',
    'The ad date has already expired.' => 'لقد انتهى تاريخ الإعلان بالفعل.',
    'The aws region where your s3 bucket is hosted.' => 'منطقة aws حيث تتم استضافة مجموعة s3 الخاصة بك.',
    'The base url used to access your s3 bucket.' => 'عنوان URL الأساسي المستخدم للوصول إلى مجموعة s3 الخاصة بك.',
    'The command is not editable. Click copy button to copy the command' => 'الأمر غير قابل للتحرير. انقر فوق زر النسخ لنسخ الأمر',
    'The commission is automatically deducted from the order value before the remaining amount is settled with the vendor or service provider.' => 'يتم خصم العمولة تلقائيًا قيمة الطلب قبل تسوية المبلغ المتبقي مع البائع أو المشرف.',
    'The company name often serves as the primary identifier for your business as a legal entity.' => 'غالبًا ما يكون اسم الشركة بمثابة المعرف الأساسي لنشاطك التجاري ككيان قانوني.',
    'The cover image is required' => 'صورة الغلاف مطلوبة',
    'The custom endpoint for your s3-compatible storage (optional for aws s3).' => 'نقطة النهاية المخصصة للتخزين المتوافق مع s3 (اختياري aws s3).',
    'The customer who used referral code will get discount when a place their first order.' => 'سيحصل العميل الذي استخدم رمز الإحالة على خصم عند تقديم طلبه الأول.',
    'The discount amount value must be gather than 0' => 'يجب أن تكون قيمة مبلغ الخصم أكبر 0',
    'The discount percent value must be gather than 0' => 'يجب أن تكون قيمة نسبة الخصم أكبر 0',
    'The execution time of a cron job is defined by the schedule when the job will be done.' => 'يتم تحديد وقت تنفيذ مهمة cron خلال الجدول الزمني الذي سيتم فيه إنجاز المهمة.',
    'The fav icon helps users quickly identify the site among multiple open tabs.' => 'يساعد رمز المفضلة المستخدمين على التعرف بسرعة على الموقع بين علامات التبويب المتعددة المفتوحة.',
    'The minimum number of points a customer must have before converting them into wallet money.' => 'الحد الأدنى لعدد النقاط التي يجب أن يمتلكها العميل قبل تحويلها إلى أموال المحفظة.',
    'The name of the s3 bucket where your files will be stored.' => 'اسم حاوية s3 حيث سيتم تخزين ملفاتك.',
    'The option you select customer will have the option to login customer app and websites' => 'سيكون لدى الخيار الذي تحدده العميل خيار تسجيل الدخول إلى تطبيق العميل ومواقع الويب',
    'The option you select customer will have the to option to login' => 'سيكون لدى الخيار الذي تحدده العميل خيار تسجيل الدخول',
    'The option you select customers will be able to log in to both the app and website based on the option you select.' => 'الخيار الذي تحدده سيتمكن العملاء تسجيل الدخول إلى كل التطبيق وموقع الويب بناءً على الخيار الذي تحدده.',
    'The option you select from below will need to verify by customer from customer app/website' => 'سيحتاج الخيار الذي تحدده أدناه إلى التحقق قبل العميل تطبيق/موقع العميل',
    'The private key paired with your access key for secure authentication.' => 'المفتاح الخاص المقترن بمفتاح الوصول الخاص بك للمصادقة الآمنة.',
    'The profile image is required' => 'الصورة الشخصية مطلوبة',
    'The remaining content will not be translated.' => 'لن يتم ترجمة المحتوى المتبقي.',
    'The remaining count updates automatically as you use services. And an option to change, renew, or change the subscription plan' => 'يتم تحديث العدد المتبقي تلقائيًا أثناء استخدامك للخدمات. وخيار لتغيير أو تجديد أو تغيير خطة الاشتراك',
    'The service availability option has been turned off. You will not receive any new booking requests until you turn on the service availability option' => 'تم إيقاف خيار توفر الخدمة. لن تتلقى أي طلبات حجز جديدة حتى تقوم بتفعيل خيار توفر الخدمة',
    'The service availability option has been turned off. You will not receive any new customized requests until you turn on the service availability option' => 'تم إيقاف خيار توفر الخدمة. لن تتلقى أي طلبات مخصصة جديدة حتى تقوم بتشغيل خيار توفر الخدمة',
    'The title of a Cron Job refers to the command that will be automatically executed at specific time intervals or dates when scheduled.' => 'يشير عنوان وظيفة Cron إلى الأمر الذي سيتم تنفيذه تلقائيًا على فترات زمنية أو تواريخ محددة عند جدولتها.',
    'The uploaded file must be an image.' => 'يجب أن يكون الملف الذي تم تحميله صورة.',
    'Your account username' => 'اسم المستخدم لحساب الخاص بك',
    'The video attachment is required' => 'مطلوب مرفق الفيديو',
    'The wallet reward a customer receives for each successful referral when the invited user places their first order.' => 'مكافأة المحفظة التي يتلقاها العميل مقابل كل إحالة ناجحة عندما يقدم المستخدم المدعو طلبه الأول.',
    'The zip extension is not enabled' => 'لم يتم تمكين ملحق الرمز البريدي',
    'Theme Mode' => 'وضع الموضوع',
    'Then activate the Addon and set up all the options.' => 'ثم فعّل الملحق وقم بإعداد جميع الخيارات.',
    'There is no advertisement created by provider yet!' => 'لا يوجد إعلان تم إنشاؤه بواسطة المشرف حتى الآن!',
    'These information will be used to create super admin credential for your admin panel.' => 'سيتم استخدام هذه المعلومات لإنشاء بيانات اعتماد المشرف المتميز للوحة المشرف الخاصة بك.',
    'They will no longer be able to combine wallet balance with other payment options.' => 'لن يتمكنوا بعد الآن الجمع بين رصيد المحفظة وخيارات الدفع الأخرى.',
    'This Month' => 'هذا الشهر',
    'This SMS gateway will work for :otp_verification or :notification through SMS.' => 'ستعمل بوابة الرسائل القصيرة هذه للتحقق :otp أو :notification خلال الرسائل القصيرة.',
    'This Year' => 'هذا العام',
    'This action will replace the current database with the selected backup.' => 'سيؤدي هذا الإجراء إلى استبدال قاعدة البيانات الحالية بالنسخة الاحتياطية المحددة.',
    'This action will replace the current database with the selected backup. Any unsaved changes made after the backup date will be lost.' => 'سيؤدي هذا الإجراء إلى استبدال قاعدة البيانات الحالية بالنسخة الاحتياطية المحددة. سيتم فقدان أي تغييرات غير محفوظة تم إجراؤها بعد تاريخ النسخ الاحتياطي.',
    'This ad is running, To delete this ad from the list, please change its status first. Once the status is updated, you can proceed with deletion' => 'هذا الإعلان قيد العرض، لحذف هذا الإعلان القائمة، يرجى تغيير حالته أولاً. بمجرد تحديث الحالة، يمكنك متابعة الحذف',
    'This ad will be pause and not show in the app or web' => 'سيتم إيقاف هذا الإعلان مؤقتًا ولن يظهر في التطبيق أو الويب',
    'This ad will be run again and will show in the app or web' => 'سيتم تشغيل هذا الإعلان مرة أخرى وسيظهر في التطبيق أو الويب',
    'This address represents the business location from which the admin operates and manages providers, customers, and service personnel.' => 'يمثل هذا العنوان موقع العمل الذي يعمل منه المسؤول ويدير المشرفين والعملاء وموظفي الخدمة.',
    'This address represents the service location from which, as a provider, you operate and manage customers, services, and service personnel.' => 'يمثل هذا العنوان موقع الخدمة الذي تقوم خلاله، كمشرف، بتشغيل وإدارة العملاء والخدمات وموظفي الخدمة.',
    'This booking request includes custom instruction by the customer. Please read all the detailed requirements before accepting the request' => 'يتضمن طلب الحجز هذا تعليمات مخصصة قبل العميل. يرجى قراءة كافة المتطلبات التفصيلية قبل قبول الطلب',
    'This booking verification list is for verifying bookings whose total amount exceeds the maximum booking amount for cash on delivery' => 'قائمة التحقق الحجز هذه مخصصة للتحقق الحجوزات التي يتجاوز إجمالي مبلغها الحد الأقصى لمبلغ الحجز نقدًا عند التسليم',
    'This button is now disable to active setup & turned on any sms gateway.' => 'تم الآن تعطيل هذا الزر للإعداد النشط وتشغيل أي بوابة رسائل نصية قصيرة.',
    'This can improve flexibility and increase successful order completions.' => 'يمكن أن يؤدي ذلك إلى تحسين المرونة وزيادة عمليات إكمال الطلبات الناجحة.',
    'This category is available in (:zones) zones. And available subcategories (:subcategories)' => 'هذه الفئة متوفرة في مناطق (:zones). والفئات الفرعية المتاحة (:subcategories)',
    'This category is not under any zone. Kindly update the category with zone' => 'هذه الفئة ليست تحت أي منطقة. يرجى تحديث الفئة مع المنطقة',
    'This currency is not supported by any of your current active digital payment gateways. Customer will not see the digital payment option & will not be able to pay digitally from website and apps' => 'هذه العملة غير مدعومة قبل أي بوابات الدفع الرقمية النشطة الحالية لديك. لن يرى العميل خيار الدفع الرقمي ولن يتمكن الدفع رقميًا موقع الويب والتطبيقات',
    'This field is required.' => 'هذه الخانة مطلوبه.',
    'This gives providers more options to join the business for growth and success.' => 'وهذا يمنح المشرفين المزيد الخيارات للانضمام إلى الأعمال لتحقيق النمو والنجاح.',
    'This helps to keep your new password secure.' => 'وهذا يساعد على الحفاظ على كلمة المرور الجديدة الخاصة بك آمنة.',
    'This info will need for employee’s future login' => 'ستحتاج هذه المعلومات لتسجيل دخول الموظف في المستقبل',
    'This is a repeat booking.' => 'هذا حجز متكرر.',
    'This is a short message shown on the website to let visitors know that the site uses cookies to collect information and improve their browsing experience' => 'هذه رسالة قصيرة تظهر على الموقع لإعلام الزوار بأن الموقع يستخدم ملفات تعريف الارتباط لجمع المعلومات وتحسين تجربة التصفح لديهم',
    'This is a short statement that shows your company owns the content on your website.' => 'هذا بيان قصير يوضح أن شركتك تمتلك المحتوى الموجود على موقع الويب الخاص بك.',
    'This is how customer will see in the app' => 'هذه هي الطريقة التي سيراها العميل في التطبيق',
    'This logo is the main visual identity of the business.' => 'هذا الشعار هو الهوية البصرية الرئيسية للشركة.',
    'This page shows your current subscription details, billing status, and available features.' => 'تعرض هذه الصفحة تفاصيل اشتراكك الحالي وحالة الفوترة والميزات المتاحة.',
    'This request is with customized instructions. Please read the customer description and instructions thoroughly and place your pricing according to this' => 'هذا الطلب مع تعليمات مخصصة. يرجى قراءة وصف العميل وتعليماته بدقة ووضع الأسعار وفقًا لذلك',
    'This requires SMS Gateway setup to be configured first.' => 'يتطلب هذا تكوين إعداد بوابة الرسائل القصيرة أولاً.',
    'This section allows you to configure SMTP email settings so the system can send emails reliably.' => 'يتيح لك هذا القسم تكوين إعدادات البريد الإلكتروني SMTP حتى يتمكن النظام إرسال رسائل البريد الإلكتروني بشكل موثوق.',
    'This section allows you to configure basic settings for your services.' => 'يتيح لك هذا القسم ضبط الإعدادات الأساسية لخدماتك.',
    'This section currently includes Time Zone and Date Format, Pagination Limit, Phone Number Visibility in Chat, and Currency configuration.' => 'يتضمن هذا القسم حاليًا المنطقة الزمنية وتنسيق التاريخ، وحدود الصفحات، وإمكانية رؤية رقم الهاتف في الدردشة، وتكوين العملة.',
    'This section is used to configure Google Map integration for your system.' => 'يُستخدم هذا القسم لتكوين تكامل خرائط Google لنظامك.',
    'This section may help user to get the update features in their app.' => 'قد يساعد هذا القسم المستخدم في الحصول على ميزات التحديث في تطبيقه.',
    'This setup connects your application with your Firebase project using official credentials provided by Google.' => 'يعمل هذا الإعداد على ربط تطبيقك بمشروع Firebase الخاص بك باستخدام بيانات الاعتماد الرسمية المقدمة Google.',
    'This social media link has already been added. Please choose a different platform or update the existing one' => 'تمت إضافة رابط الوسائط الاجتماعية هذا بالفعل. يرجى اختيار نظام أساسي مختلف أو تحديث النظام الحالي',
    'This view is from the user app.' => 'هذا العرض تطبيق المستخدم.',
    'This view is from the user app. This is how customer will see in the app' => 'هذا العرض تطبيق المستخدم. هذه هي الطريقة التي سيراها العميل في التطبيق',
    'This week' => 'هذا الاسبوع',
    'This will be shown as the level for the additional charge to the customers.' => 'سيتم عرض هذا كمستوى الرسوم الإضافية للعملاء.',
