    'To Integrate add-on to your system please follow the instruction below' => 'لدمج الوظيفة الإضافية في نظامك، يرجى اتباع التعليمات أدناه',
    'To activate the subscription-based business model, first add a subscription package from :subscription_packages_link.' => 'لتفعيل نموذج الأعمال القائم على الاشتراك، قم أولاً بإضافة حزمة اشتراك رابط حزم :subscription.',
    'To change currency setup, visit' => 'لتغيير إعداد العملة، تفضل بزيارة',
    'To change currency setup, visit the :business_information_link page.' => 'لتغيير إعداد العملة، قم بزيارة صفحة رابط معلومات :business.',
    'To configure OTP in Firebase, you must create a Firebase project first.' => 'لتكوين OTP في Firebase، يجب عليك إنشاء مشروع Firebase أولاً.',
    'To continue using :business_name, please choose a paid business plan.' => 'لمواصلة استخدام اسم :business، يرجى اختيار خطة عمل مدفوعة الأجر.',
    'To enable Email verification, please set up the Email configuration and turn on the status first.' => 'لتمكين التحقق البريد الإلكتروني، يرجى إعداد تكوين البريد الإلكتروني وتشغيل الحالة أولاً.',
    'To enable Phone verification, please set up the SMS configuration and turn on the status first.' => 'لتمكين التحقق الهاتف، يرجى إعداد تكوين الرسائل القصيرة وتشغيل الحالة أولاً.',
    'To enable map-based features such as location selection, serviceman tracking, and distance calculation, you must provide valid Google Map API keys.' => 'لتمكين الميزات المستندة إلى الخريطة مثل اختيار الموقع وتتبع الخدمة وحساب المسافة، يجب عليك توفير مفاتيح Google Map API صالحة.',
    'To enable the Apple ID Login option, please set up the Apple ID configuration first.' => 'لتمكين خيار تسجيل الدخول إلى معرف Apple، يرجى إعداد تكوين معرف Apple أولاً.',
    'To enable the Apple login system, please set up the Apple configuration first.' => 'لتمكين نظام تسجيل الدخول إلى Apple، يرجى إعداد تكوين Apple أولاً.',
    'To enable the Facebook Login option, please set up the Facebook configuration first.' => 'لتمكين خيار تسجيل الدخول عبر Facebook، يرجى إعداد تكوين Facebook أولاً.',
