    'To enable this feature must be activated' => 'لتمكين هذه الميزة يجب تفعيلها',
    'To enable this feature, you have to activate social media from the Social media login setup option below.' => 'لتمكين هذه الميزة، يجب عليك تنشيط وسائل التواصل الاجتماعي خيار إعداد تسجيل الدخول إلى وسائل التواصل الاجتماعي أدناه.',
    'To finalize the process and make payment arrangements, please contact our' => 'لإنهاء العملية وإجراء ترتيبات الدفع، يرجى الاتصال بنا',
    'To get site key and secret key Go to the Credentials page' => 'للحصول على مفتاح الموقع والمفتاح السري، انتقل إلى صفحة بيانات الاعتماد',
    'To get site key and secret keyGo to the Credentials page' => 'للحصول على مفتاح الموقع والمفتاح السري، انتقل إلى صفحة بيانات الاعتماد',
    'To make these payment options available, you must enable the Digital payment option from the :business_information_link page.' => 'لإتاحة خيارات الدفع هذه، يجب عليك تمكين خيار الدفع الرقمي صفحة رابط معلومات :business.',
    'To make these payment options available, you must enable the Offline payment option from the :business_information_link page.' => 'لإتاحة خيارات الدفع هذه، يجب عليك تمكين خيار الدفع دون اتصال بالإنترنت صفحة رابط معلومات :business.',
    'To renew your subscription & maintain uninterrupted service, please follow the link below' => 'لتجديد اشتراكك والحفاظ على الخدمة دون انقطاع، يرجى اتباع الرابط أدناه',
    'To set different commission for commission based, set the Default commission' => 'لتعيين عمولة مختلفة على أساس العمولة، قم بتعيين العمولة الافتراضية',
    'To use any payment method for Partial payment you need to active them from Previous Section, otherwise the payment method will remain disable.' => 'لاستخدام أي طريقة دفع للدفع الجزئي، يتعين عليك تنشيطها القسم السابق، وإلا ستظل طريقة الدفع معطلة.',
    'To use digital payments, you need to set up at least one payment method' => 'لاستخدام الدفعات الرقمية، يتعين عليك إعداد طريقة دفع واحدة على الأقل',
    'To use offline payments, you need to set up at least one offline payment method.' => 'لاستخدام الدفعات دون الاتصال بالإنترنت، يتعين عليك إعداد طريقة دفع واحدة على الأقل دون الاتصال بالإنترنت.',
