    'You can also allow automatic account creation using guest information to convert guests into registered users.' => 'يمكنك أيضًا السماح بإنشاء الحساب تلقائيًا باستخدام معلومات الضيف لتحويل الضيوف إلى مستخدمين مسجلين.',
    'You can also mark a method as default, update its information, or remove it if necessary.' => 'يمكنك أيضًا وضع علامة على الطريقة كافتراضية، أو تحديث معلوماتها، أو إزالتها إذا لزم الأمر.',
    'You can create an ad on behalf of a provider.' => 'يمكنك إنشاء إعلان نيابة عن المشرف.',
