    'You can get the PHP file path from your server. Here is an example of Apache Server -' => 'يمكنك الحصول على مسار ملف PHP الخادم الخاص بك. فيما يلي مثال لخادم Apache -',
    'You can manage all your storage files from' => 'يمكنك إدارة كافة ملفات التخزين الخاصة بك من',
