    'You can manage your normal discount from :normal_discount_link.' => 'يمكنك إدارة الخصم العادي الخاص بك رابط الخصم :normal.',
    'You can not consume your subscription after :date' => 'لا يمكنك استهلاك اشتراكك بعد :date',
    'You can not turn off the SMS configuration status since the Phone verification status is active in login setup' => 'لا يمكنك إيقاف تشغيل حالة تكوين الرسائل القصيرة نظرًا لأن حالة التحقق الهاتف نشطة في إعداد تسجيل الدخول',
    'You can not turn off the email configuration status since the Email verification status is active in login setup' => 'لا يمكنك إيقاف تشغيل حالة تكوين البريد الإلكتروني نظرًا لأن حالة التحقق البريد الإلكتروني نشطة في إعداد تسجيل الدخول',
    'You can not undo this after deleting this logs' => 'لا يمكنك التراجع عن هذا بعد حذف هذه السجلات',
    'You can now access your account & reset your password from our app & website.' => 'يمكنك الآن الوصول إلى حسابك وإعادة تعيين كلمة المرور الخاصة بك تطبيقنا وموقعنا الإلكتروني.',
    'You can offer providers a free trial to experience the system overall.' => 'يمكنك تقديم نسخة تجريبية مجانية للمشرفين لتجربة النظام بشكل عام.',
    'You can only add up to 10 custom pages.' => 'يمكنك إضافة ما يصل إلى 10 صفحات مخصصة فقط.',
    'You can see all inactive suspended providers on the :provider_list_link page.' => 'يمكنك رؤية جميع المشرفين المعلقين غير النشطين على صفحة رابط قائمة :provider.',
    'You can see all providers service man list from this' => 'يمكنك رؤية قائمة جميع المشرفين هذا',
    'You can see status wise advertisement history and adjust edit, pause, resume, resubmit, or delete as needed.' => 'يمكنك الاطلاع على سجل الإعلانات حسب الحالة وضبط التعديل أو الإيقاف المؤقت أو الاستئناف أو إعادة الإرسال أو الحذف حسب الحاجة.',
